basic.fetcher:
(function (args, reqOptions) {
  return {
    url: `${window.origin}/${reqOptions.sl}/Widgets/EmployeeDirectory/GetEmployeeDetails`,
    method: 'GET',
    headers: {
      "Content-Type": "application/json",
      "x-requested-with": "XMLHttpRequest"

    },
    params: {
      "searchText": args.empSearch
    }
  };
})

basic.transformer:
(function(data, args, reqOptions) {
  const details = data.map(x=>({
    employeeName : x.EmployeeDisplayName,
    employeeId : x.EmployeeDisplayNumber
  }))
  return details;
})

